package org.familyhealthcare.service.alertworkflow;

import org.familyhealthcare.service.workflow.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jdbc.core.*;
import org.springframework.jdbc.support.*;
import org.springframework.stereotype.Repository;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;

/** Fixed internal persistence, not a public business API. Services authorize before/after locks and replay. */
@Repository
@ConditionalOnProperty(name="alert-workflow.enabled",havingValue="true")
public class AlertWorkflowRepository {
    private final JdbcTemplate jdbc;private final AlertWorkflowProperties properties;private final AlertWorkflowAuthorizationService auth;
    private static final String ALERT="SELECT id,patient_id,user_id,source_type,source_id,workflow_version,workflow_state,workflow_mode,cycle_no,source_revision,metric_key,responsible_user_id,due_at,accepted_by,accepted_at,lock_version,current_handling_event_id,current_feedback_event_id,source_review_required,reassignment_required,classification_json,closed_by,closed_at,closure_reason,status FROM alert_record WHERE id=?";
    public AlertWorkflowRepository(JdbcTemplate jdbc,AlertWorkflowProperties properties,AlertWorkflowAuthorizationService auth){this.jdbc=jdbc;this.properties=properties;this.auth=auth;}
    /** Non-identifying public read boundary; an absent/unauthorized ID always has the same denial. */
    public Map<String,Object> readAlert(long actor,long id){
        properties.requireEnabled();auth.requireActiveActor(actor);List<Long> patients=jdbc.query("SELECT patient_id FROM alert_record WHERE id=? AND workflow_version=1",(rs,i)->rs.getLong(1),id);
        if(patients.isEmpty())throw AlertWorkflowException.denied();auth.requireRead(actor,patients.get(0));Map<String,Object> row=one(ALERT,this::alert,id);auth.requireRead(actor,patients.get(0));return row;
    }
    public Map<String,Object> readSource(long actor,long patient,String type,long id){properties.requireEnabled();if(!auth.canReadEvidence(actor,patient,type,id))throw AlertWorkflowException.denied();Map<String,Object> row=source(type,id,false);if(row==null||((Number)row.get("patientId")).longValue()!=patient||!auth.canReadEvidence(actor,patient,type,id))throw AlertWorkflowException.denied();return row;}
    /** Lock-bearing internal lookups require the actual same-datasource READ_COMMITTED transaction. */
    public Map<String,Object> lockAlert(long id){write();positive(id,"alertId");return one(ALERT+" FOR UPDATE",this::alert,id);}
    public Map<String,Object> lockSource(String type,long id){write();return source(type,id,true);}
    public long createSourceIdentity(String type,long sourceId,long patient){
        write();AlertWorkflowContracts.choice(type,"sourceType",AlertWorkflowContracts.SOURCE_TYPES);positive(sourceId,"sourceId");positive(patient,"patientId");Map<String,Object> source=source(type,sourceId,true);if(source==null||((Number)source.get("patientId")).longValue()!=patient)throw AlertWorkflowException.denied();
        Instant now=properties.now();return insert("INSERT INTO alert_source_identity(source_type,source_id,patient_id,current_revision,status,lock_version,created_at,updated_at) VALUES(?,?,?,1,'ACTIVE',0,?,?)",type,sourceId,patient,now,now);
    }
    /** Initial capture has no invented correction reason. Later callers must pass the actual action provenance. */
    public long appendSourceRevision(long identity,long revision,long actor,Instant occurred,Map<String,Object> snapshot){
        return appendSourceRevision(identity,revision,actor,occurred,snapshot,null,"ACTIVE");
    }
    public long appendSourceRevision(long identity,long revision,long actor,Instant occurred,Map<String,Object> snapshot,String reason,String status){
        write();positive(identity,"sourceIdentityId");positive(revision,"sourceRevision");positive(actor,"actorId");occurrence(occurred);AlertWorkflowContracts.validateSourceSnapshot(snapshot);
        AlertWorkflowContracts.choice(status,"sourceStatus",set("ACTIVE","INVALIDATED"));
        if(revision==1&&!"ACTIVE".equals(status))throw AlertWorkflowException.invalid("Initial source capture must be active.");
        String bounded=revision>1||reason!=null?AlertWorkflowContracts.requireText(reason,"reason",1000):null;
        // Correction callers already hold every discovered plan parent and native source lock.
        // The map is derived from receipt relationships here, never accepted from a request/snapshot.
        Map<String,Object> actionVersions=new LinkedHashMap<>();
        if(revision>1)jdbc.query("SELECT DISTINCT a.id,a.lock_version FROM alert_source_identity s JOIN care_plan_evidence v ON v.source_id=s.source_id AND v.source_type=CASE WHEN s.source_type='HEALTH_MEASUREMENT' THEN 'MEASUREMENT' ELSE s.source_type END JOIN care_plan_event e ON e.id=v.event_id JOIN care_plan_action a ON a.id=e.action_id WHERE s.id=? ORDER BY a.id",rs->{actionVersions.put(Long.toString(rs.getLong(1)),rs.getLong(2));},identity);
        return insert("INSERT INTO alert_source_revision(source_identity_id,revision_no,recorded_by,occurred_at,recorded_at,snapshot_json,correction_reason,source_status,action_versions_json) VALUES(?,?,?,?,?,?,?,?,?)",identity,revision,actor,occurred,properties.now(),WorkflowData.json(snapshot),bounded,status,WorkflowData.json(actionVersions));
    }
    public void advanceSourceRevision(long identity,long expectedVersion,long revision,String status){
        write();positive(identity,"sourceIdentityId");positive(revision,"sourceRevision");AlertWorkflowContracts.requireVersion(expectedVersion);AlertWorkflowContracts.choice(status,"sourceStatus",set("ACTIVE","INVALIDATED"));
        if(jdbc.queryForObject("SELECT COUNT(*) FROM alert_source_revision WHERE source_identity_id=? AND revision_no=? AND source_status=?",Integer.class,identity,revision,status)!=1)throw AlertWorkflowException.invalid("source revision is missing.");
        int changed=update("UPDATE alert_source_identity SET current_revision=?,status=?,lock_version=lock_version+1,updated_at=? WHERE id=? AND lock_version=? AND current_revision<=?",revision,status,properties.now(),identity,expectedVersion,revision);if(changed!=1)throw AlertWorkflowException.conflict();
    }
    public Map<String,Object> sourceRevision(long identity,long revision){properties.requireEnabled();positive(identity,"sourceIdentityId");positive(revision,"sourceRevision");return one("SELECT id,source_identity_id,revision_no,recorded_by,occurred_at,recorded_at,snapshot_json,correction_reason,source_status FROM alert_source_revision WHERE source_identity_id=? AND revision_no=?",this::sourceRevisionRow,identity,revision);}
    /** Internal persistence only; the bridge independently authorizes and locks the native identity. */
    public List<Map<String,Object>> sourceRevisions(long identity,long after,int limit){properties.requireEnabled();positive(identity,"sourceIdentityId");AlertWorkflowContracts.requireVersion(after);if(limit<1||limit>101)throw AlertWorkflowException.invalid("Invalid history limit.");return query("SELECT id,source_identity_id,revision_no,recorded_by,occurred_at,recorded_at,snapshot_json,correction_reason,source_status FROM alert_source_revision WHERE source_identity_id=? AND revision_no>? ORDER BY revision_no LIMIT ?",this::sourceRevisionRow,identity,after,limit);}
    private Map<String,Object> sourceRevisionRow(ResultSet rs,int index)throws SQLException{return WorkflowData.map("id",rs.getLong("id"),"sourceIdentityId",rs.getLong("source_identity_id"),"sourceRevision",rs.getLong("revision_no"),"recordedBy",rs.getLong("recorded_by"),"occurredAt",WorkflowData.time(rs,"occurred_at"),"recordedAt",WorkflowData.time(rs,"recorded_at"),"snapshot",WorkflowData.object(rs.getString("snapshot_json")),"correctionReason",rs.getString("correction_reason"),"sourceStatus",rs.getString("source_status"));}
    /** Initial storage only; lifecycle/assignee/clinical decisions belong to the authorized domain service. */
    public long createAlert(Map<String,Object> values){
        write();AlertWorkflowContracts.fields(values,set("patientId","ownerUserId","sourceType","sourceId","sourceRevision","metric","classification","workflowMode","responsibleUserId","dueAt"));
        long patient=AlertWorkflowContracts.requireId(values.get("patientId"),"patientId"),owner=AlertWorkflowContracts.requireId(values.get("ownerUserId"),"ownerUserId"),sourceId=AlertWorkflowContracts.requireId(values.get("sourceId"),"sourceId"),revision=AlertWorkflowContracts.requireId(values.get("sourceRevision"),"sourceRevision");
        String type=AlertWorkflowContracts.choice(values.get("sourceType"),"sourceType",AlertWorkflowContracts.SOURCE_TYPES),metric=AlertWorkflowContracts.choice(values.get("metric"),"metric",AlertWorkflowContracts.METRICS),mode=AlertWorkflowContracts.choice(values.get("workflowMode"),"workflowMode",AlertWorkflowContracts.MODES);
        classification(values.get("classification"));Long assignee=idOrNull(values.get("responsibleUserId"),"responsibleUserId");Instant due=instant(values.get("dueAt"));
        if(jdbc.queryForObject("SELECT COUNT(*) FROM alert_source_identity s JOIN alert_source_revision r ON r.source_identity_id=s.id WHERE s.source_type=? AND s.source_id=? AND s.patient_id=? AND r.revision_no=?",Integer.class,type,sourceId,patient,revision)!=1)throw AlertWorkflowException.denied();
        return insert("INSERT INTO alert_record(patient_id,user_id,alert_type,alert_title,source_type,source_id,status,workflow_version,workflow_state,workflow_mode,cycle_no,source_revision,metric_key,responsible_user_id,due_at,lock_version,classification_json) VALUES(?,?,'MEASUREMENT_FOLLOW_UP','Health measurement follow-up',?,?,'PENDING',1,'OPEN',?,1,?,?,?, ?,0,?)",patient,owner,type,sourceId,mode,revision,metric,assignee,due,WorkflowData.json(values.get("classification")));
    }
    /** Writes the full locked aggregate projection, with an optimistic version predicate. No transition inference. */
    public void saveAlert(Map<String,Object> row,long expectedVersion){
        write();long id=AlertWorkflowContracts.requireId(row.get("id"),"alertId");AlertWorkflowContracts.requireVersion(expectedVersion);String state=AlertWorkflowContracts.choice(row.get("workflowState"),"workflowState",AlertWorkflowContracts.STATES),mode=AlertWorkflowContracts.choice(row.get("workflowMode"),"workflowMode",AlertWorkflowContracts.MODES);long cycle=AlertWorkflowContracts.requireId(row.get("cycleNo"),"cycleNo"),revision=AlertWorkflowContracts.requireId(row.get("sourceRevision"),"sourceRevision");if(cycle>Integer.MAX_VALUE)throw AlertWorkflowException.invalid("cycleNo is too large.");classification(row.get("classification"));
        String status="CLOSED".equals(state)?"RESOLVED":"CANCELLED".equals(state)?"CANCELLED":"OPEN".equals(state)?"PENDING":"ACKNOWLEDGED";
        int changed=update("UPDATE alert_record SET workflow_state=?,workflow_mode=?,cycle_no=?,source_revision=?,responsible_user_id=?,due_at=?,accepted_by=?,accepted_at=?,current_handling_event_id=?,current_feedback_event_id=?,source_review_required=?,reassignment_required=?,classification_json=?,closed_by=?,closed_at=?,closure_reason=?,status=?,acknowledged_by=?,acknowledged_at=?,resolved_by=?,resolved_at=?,lock_version=lock_version+1 WHERE id=? AND workflow_version=1 AND lock_version=?",state,mode,cycle,revision,idOrNull(row.get("responsibleUserId"),"responsibleUserId"),instant(row.get("dueAt")),idOrNull(row.get("acceptedBy"),"acceptedBy"),instant(row.get("acceptedAt")),idOrNull(row.get("currentHandlingEventId"),"currentHandlingEventId"),idOrNull(row.get("currentFeedbackEventId"),"currentFeedbackEventId"),flag(row.get("sourceReviewRequired")),flag(row.get("reassignmentRequired")),WorkflowData.json(row.get("classification")),idOrNull(row.get("closedBy"),"closedBy"),instant(row.get("closedAt")),row.get("closureReason")==null?null:AlertWorkflowContracts.requireText(row.get("closureReason"),"closureReason",1000),status,idOrNull(row.get("acceptedBy"),"acceptedBy"),instant(row.get("acceptedAt")),"CLOSED".equals(state)?idOrNull(row.get("closedBy"),"closedBy"):null,"CLOSED".equals(state)?instant(row.get("closedAt")):null,id,expectedVersion);
        if(changed!=1)throw AlertWorkflowException.conflict();
    }
    public void linkSource(long identity,String type,long sourceId,long revision,String metric,long alert){write();positive(identity,"sourceIdentityId");positive(sourceId,"sourceId");positive(revision,"sourceRevision");positive(alert,"alertId");AlertWorkflowContracts.choice(type,"sourceType",AlertWorkflowContracts.SOURCE_TYPES);AlertWorkflowContracts.choice(metric,"metric",AlertWorkflowContracts.METRICS);
        // A patient's unrelated alert must never become this native identity/metric's deduplication target.
        // Historical revision links remain valid when the matching aggregate advances to a later revision.
        if(jdbc.queryForObject("SELECT COUNT(*) FROM alert_source_identity s JOIN alert_source_revision r ON r.source_identity_id=s.id AND r.revision_no=? JOIN alert_record a ON a.patient_id=s.patient_id WHERE s.id=? AND s.source_type=? AND s.source_id=? AND a.id=? AND a.workflow_version=1 AND a.alert_type='MEASUREMENT_FOLLOW_UP' AND a.source_type=s.source_type AND a.source_id=s.source_id AND a.metric_key=?",Integer.class,revision,identity,type,sourceId,alert,metric)!=1)throw AlertWorkflowException.denied();
        insert("INSERT INTO alert_source_link(source_identity_id,source_type,source_id,source_revision,metric_key,alert_id) VALUES(?,?,?,?,?,?)",identity,type,sourceId,revision,metric,alert);}
    public long appendEvent(long alert,long patient,int cycle,String type,Map<String,Object> actor,String from,String to,String note,String entryMode,Instant occurred,Map<String,Object> payload){
        write();if("DUE".equals(type)||"SYSTEM".equals(actor.get("actorRole")))throw AlertWorkflowException.invalid("System due events use the internal scheduler boundary.");positive(alert,"alertId");positive(patient,"patientId");positive(cycle,"cycleNo");String event=AlertWorkflowContracts.requireText(type,"eventType",40);long actorId=AlertWorkflowContracts.requireId(actor.get("actorId"),"actorId");String name=AlertWorkflowContracts.requireText(actor.get("actorName"),"actorName",100),role=AlertWorkflowContracts.requireText(actor.get("actorRole"),"actorRole",50),relation=AlertWorkflowContracts.requireText(actor.get("actorRelation"),"actorRelation",100);if(from!=null)AlertWorkflowContracts.choice(from,"fromState",AlertWorkflowContracts.STATES);AlertWorkflowContracts.choice(to,"toState",AlertWorkflowContracts.STATES);if(entryMode!=null)AlertWorkflowContracts.choice(entryMode,"entryMode",set("SELF","ASSISTED"));if(occurred!=null)occurrence(occurred);if(payload==null)throw AlertWorkflowException.invalid("event payload is required.");
        return insert("INSERT INTO alert_event(alert_id,patient_id,actor_id,actor_name,from_status,to_status,note,event_type,cycle_no,actor_role,actor_relation,entry_mode,occurred_at,recorded_at,payload_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",alert,patient,actorId,name,from,to,note==null?null:AlertWorkflowContracts.requireText(note,"note",2000),event,cycle,role,relation,entryMode,occurred,properties.now(),WorkflowData.json(payload));
    }
    /** Server-only system event. Reacquire the aggregate lock and validate the exact current deadline. */
    long appendDueEvent(long alertId,Instant now,String dueKey){
        write();Map<String,Object> alert=lockAlert(alertId);
        if(alert==null||alert.get("dueAt")==null||Arrays.asList("CLOSED","CANCELLED").contains(alert.get("workflowState")))throw AlertWorkflowException.conflict();
        Instant due=Instant.parse((String)alert.get("dueAt"));int cycle=((Number)alert.get("cycleNo")).intValue();
        if(due.isAfter(now)||!AlertWorkflowNotificationWorker.dueKey(alertId,cycle,due).equals(dueKey))throw AlertWorkflowException.conflict();
        String state=(String)alert.get("workflowState");
        return insert("INSERT INTO alert_event(alert_id,patient_id,actor_id,actor_name,from_status,to_status,note,event_type,cycle_no,actor_role,actor_relation,entry_mode,occurred_at,recorded_at,payload_json) VALUES(?,?,NULL,NULL,?,?,NULL,'DUE',?,'SYSTEM','SCHEDULER',NULL,?,?,?)",alertId,alert.get("patientId"),state,state,cycle,now,now,WorkflowData.json(WorkflowData.map("dueKey",dueKey,"dueAt",due.toString())));
    }
    public void addEvidence(long event,String type,long sourceId,Long revision,Long dependencyVersion,String state){
        write();positive(event,"eventId");positive(sourceId,"sourceId");AlertWorkflowContracts.choice(type,"sourceType",AlertWorkflowContracts.EVIDENCE_TYPES);if(revision!=null)positive(revision,"sourceRevision");if(dependencyVersion!=null)AlertWorkflowContracts.requireVersion(dependencyVersion);AlertWorkflowContracts.choice(state,"dependencyState",set("VALID","REFERENCE_CHANGED","WITHDRAWN"));
        if(AlertWorkflowContracts.SOURCE_TYPES.contains(type)&&revision==null||"CARE_PLAN_ACTION".equals(type)&&dependencyVersion==null)throw AlertWorkflowException.invalid("evidence version is required.");
        if(jdbc.queryForObject("SELECT COUNT(*) FROM alert_evidence WHERE event_id=?",Integer.class,event)>=5)throw AlertWorkflowException.invalid("at most five evidence references are permitted.");
        insert("INSERT INTO alert_evidence(event_id,source_type,source_id,source_revision,dependency_version,dependency_state) VALUES(?,?,?,?,?,?)",event,type,sourceId,revision,dependencyVersion,state);
    }
    public List<Map<String,Object>> events(long alert,long after,int limit){properties.requireEnabled();positive(alert,"alertId");AlertWorkflowContracts.requireVersion(after);if(limit<1||limit>100)throw AlertWorkflowException.invalid("limit must be between 1 and 100.");return query("SELECT id,alert_id,patient_id,actor_id,actor_name,event_type,cycle_no,actor_role,actor_relation,entry_mode,from_status,to_status,note,occurred_at,recorded_at,payload_json FROM alert_event WHERE alert_id=? AND id>? ORDER BY id LIMIT ?",(rs,i)->WorkflowData.map("id",rs.getLong("id"),"alertId",rs.getLong("alert_id"),"patientId",rs.getLong("patient_id"),"actorId",WorkflowData.nullableId(rs,"actor_id"),"actorName",rs.getString("actor_name"),"eventType",rs.getString("event_type"),"cycleNo",rs.getInt("cycle_no"),"actorRole",rs.getString("actor_role"),"actorRelation",rs.getString("actor_relation"),"entryMode",rs.getString("entry_mode"),"fromState",rs.getString("from_status"),"toState",rs.getString("to_status"),"note",rs.getString("note"),"occurredAt",WorkflowData.time(rs,"occurred_at"),"recordedAt",WorkflowData.time(rs,"recorded_at"),"payload",rs.getString("payload_json")==null?null:WorkflowData.object(rs.getString("payload_json"))),alert,after,limit);}
    public List<Map<String,Object>> evidence(long event){properties.requireEnabled();positive(event,"eventId");return query("SELECT id,event_id,source_type,source_id,source_revision,dependency_version,dependency_state FROM alert_evidence WHERE event_id=? ORDER BY id",(rs,i)->WorkflowData.map("id",rs.getLong("id"),"eventId",rs.getLong("event_id"),"sourceType",rs.getString("source_type"),"sourceId",rs.getLong("source_id"),"sourceRevision",WorkflowData.nullableId(rs,"source_revision"),"dependencyVersion",WorkflowData.nullableId(rs,"dependency_version"),"dependencyState",rs.getString("dependency_state")),event);}
    public Map<String,Object> executeCommand(WorkflowCommandExecutor.Domain domain,long actor,String key,String payload,Long aggregate,long version,Supplier<Map<String,Object>> change){
        write();if(domain!=WorkflowCommandExecutor.Domain.ALERT&&domain!=WorkflowCommandExecutor.Domain.MEASUREMENT)throw AlertWorkflowException.invalid("Unsupported workflow command domain.");
        try{return WorkflowCommandExecutor.execute(jdbc,domain,actor,key,payload,aggregate,version,properties.now(),change);}catch(WorkflowException e){throw new AlertWorkflowException(e.getStatus(),e.getErrorCode(),e.getMessage());}
    }
    private Map<String,Object> source(String type,long id,boolean lock){
        properties.requireEnabled();AlertWorkflowContracts.choice(type,"sourceType",AlertWorkflowContracts.SOURCE_TYPES);positive(id,"sourceId");Map<String,Object> row;
        if("HEALTH_MEASUREMENT".equals(type))row=one("SELECT id,patient_id,recorded_by,metric_type,value_primary,value_secondary,unit,measured_at,source_type FROM health_measurement WHERE id=?"+(lock?" FOR UPDATE":""),(rs,i)->WorkflowData.map("id",rs.getLong("id"),"patientId",rs.getLong("patient_id"),"recordedBy",rs.getLong("recorded_by"),"metricType",rs.getString("metric_type"),"valuePrimary",rs.getBigDecimal("value_primary"),"valueSecondary",rs.getBigDecimal("value_secondary"),"unit",rs.getString("unit"),"measuredAt",legacyTime(rs,"measured_at"),"sourceKind",rs.getString("source_type")),id);
        else row=one("SELECT id,patient_id,user_id,record_date,record_time,measure_type,systolic_bp,diastolic_bp,blood_glucose,bg_unit,measure_period,verification_status FROM bp_self_monitor_record WHERE id=?"+(lock?" FOR UPDATE":""),(rs,i)->WorkflowData.map("id",rs.getLong("id"),"patientId",WorkflowData.nullableId(rs,"patient_id"),"userId",rs.getLong("user_id"),"recordDate",rs.getString("record_date"),"recordTime",rs.getString("record_time"),"measureType",rs.getString("measure_type"),"systolicBp",nullableInt(rs,"systolic_bp"),"diastolicBp",nullableInt(rs,"diastolic_bp"),"bloodGlucose",rs.getBigDecimal("blood_glucose"),"bgUnit",rs.getString("bg_unit"),"measurePeriod",rs.getString("measure_period"),"verificationStatus",rs.getString("verification_status")),id);
        if(row==null)return null;row.put("sourceType",type);
        Map<String,Object> identity=one("SELECT id,current_revision,status,lock_version FROM alert_source_identity WHERE source_type=? AND source_id=?"+(lock?" FOR UPDATE":""),(rs,i)->WorkflowData.map("sourceIdentityId",rs.getLong("id"),"sourceRevision",rs.getLong("current_revision"),"sourceStatus",rs.getString("status"),"sourceVersion",rs.getLong("lock_version")),type,id);
        if(identity==null){row.put("sourceIdentityId",null);row.put("sourceRevision",0L);row.put("sourceStatus","ACTIVE");row.put("sourceVersion",0L);}else row.putAll(identity);return row;
    }
    private Map<String,Object> alert(ResultSet rs,int ignored)throws SQLException{return WorkflowData.map("id",rs.getLong("id"),"patientId",rs.getLong("patient_id"),"ownerUserId",rs.getLong("user_id"),"sourceType",rs.getString("source_type"),"sourceId",WorkflowData.nullableId(rs,"source_id"),"workflowVersion",rs.getInt("workflow_version"),"workflowState",rs.getString("workflow_state"),"workflowMode",rs.getString("workflow_mode"),"cycleNo",rs.getInt("cycle_no"),"sourceRevision",WorkflowData.nullableId(rs,"source_revision"),"metric",rs.getString("metric_key"),"responsibleUserId",WorkflowData.nullableId(rs,"responsible_user_id"),"dueAt",WorkflowData.time(rs,"due_at"),"acceptedBy",WorkflowData.nullableId(rs,"accepted_by"),"acceptedAt",WorkflowData.time(rs,"accepted_at"),"lockVersion",rs.getLong("lock_version"),"currentHandlingEventId",WorkflowData.nullableId(rs,"current_handling_event_id"),"currentFeedbackEventId",WorkflowData.nullableId(rs,"current_feedback_event_id"),"sourceReviewRequired",rs.getBoolean("source_review_required"),"reassignmentRequired",rs.getBoolean("reassignment_required"),"classification",rs.getString("classification_json")==null?null:WorkflowData.object(rs.getString("classification_json")),"closedBy",WorkflowData.nullableId(rs,"closed_by"),"closedAt",WorkflowData.time(rs,"closed_at"),"closureReason",rs.getString("closure_reason"),"legacyStatus",rs.getString("status"));}
    private void write(){properties.requireEnabled();WorkflowData.mutationTransaction(jdbc);}
    private long insert(String sql,Object...args){KeyHolder keys=new GeneratedKeyHolder();jdbc.update(connection->{PreparedStatement ps=connection.prepareStatement(sql,new String[]{"id"});bind(ps,args);return ps;},keys);Number id=keys.getKey();if(id==null)throw new IllegalStateException("Insert did not produce an ID.");return id.longValue();}
    private int update(String sql,Object...args){return jdbc.update(connection->{PreparedStatement ps=connection.prepareStatement(sql);bind(ps,args);return ps;});}
    private <T> List<T> query(String sql,RowMapper<T> mapper,Object...args){return jdbc.query(connection->{PreparedStatement ps=connection.prepareStatement(sql);bind(ps,args);return ps;},mapper);}
    private <T> T one(String sql,RowMapper<T> mapper,Object...args){List<T> rows=query(sql,mapper,args);if(rows.size()>1)throw new IllegalStateException("Non-unique storage identity.");return rows.isEmpty()?null:rows.get(0);}
    private void bind(PreparedStatement ps,Object[] args)throws SQLException{for(int i=0;i<args.length;i++){if(args[i] instanceof Instant)WorkflowData.time(ps,i+1,(Instant)args[i]);else ps.setObject(i+1,args[i]);}}
    private void positive(long value,String name){AlertWorkflowContracts.requireId(value,name);}
    private Long idOrNull(Object value,String name){return value==null?null:AlertWorkflowContracts.requireId(value,name);}
    private Instant instant(Object value){if(value==null)return null;if(value instanceof Instant)return AlertWorkflowContracts.parseOffsetInstant(value.toString());if(!(value instanceof String))throw AlertWorkflowException.invalid("time must include an ISO-8601 offset.");return AlertWorkflowContracts.parseOffsetInstant((String)value);}
    private void occurrence(Instant occurred){if(occurred==null)throw AlertWorkflowException.invalid("occurredAt is required.");AlertWorkflowContracts.requireOccurredAt(occurred.toString(),properties.now());}
    private int flag(Object value){if(value instanceof Boolean)return(Boolean)value?1:0;long number=AlertWorkflowContracts.requireVersion(value);if(number>1)throw AlertWorkflowException.invalid("flag must be boolean.");return(int)number;}
    private void classification(Object value){if(!(value instanceof Map))throw AlertWorkflowException.invalid("classification snapshot is required.");}
    private static Set<String> set(String...values){return new HashSet<>(Arrays.asList(values));}
    private static Integer nullableInt(ResultSet rs,String column)throws SQLException{int value=rs.getInt(column);return rs.wasNull()?null:value;}
    /** Existing journey DATETIME is a legacy local wall time, intentionally without a UTC Z suffix. */
    private static String legacyTime(ResultSet rs,String column)throws SQLException{LocalDateTime value=rs.getObject(column,LocalDateTime.class);return value==null?null:value.toString();}
}
